use bytes::BytesMut;
use quinn_proto::{coding::Codec, transport_parameters::TransportParameters, FixedLengthConnectionIdParser, PartialDecode, ProtectedHeader, Side, VarInt, DEFAULT_SUPPORTED_VERSIONS};

