    for input in [vec![0x20, 0], vec![0x20, 1, 0x40], vec![0xc0, 0, 0, 0, 0xff, 0x04, 0xde, 0x1b, 0]] {
        let outcome = catch_unwind(|| TransportParameters::read(Side::Server, &mut input.as_slice()));
